import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.H2uwQeTl.js";const p=JSON.parse('{"title":"The admin area","description":"","frontmatter":{},"headers":[],"relativePath":"docs/admin.md","filePath":"docs/admin.md"}'),r={name:"docs/admin.md"};function i(s,e,d,h,c,l){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="the-admin-area" tabindex="-1">The admin area <a class="header-anchor" href="#the-admin-area" aria-label="Permalink to &quot;The admin area&quot;">​</a></h1><p>The admin area is where the maintainer looks after the catalog, the accounts and the server&#39;s settings. It is a section of the website under <code>/admin</code>, backed by routes under <code>/api/v1/admin/</code>. The work is tracked in <a href="https://github.com/tkint/coach-poulpy/issues/26" target="_blank" rel="noreferrer">#26</a>.</p><h2 id="who-can-open-it" tabindex="-1">Who can open it <a class="header-anchor" href="#who-can-open-it" aria-label="Permalink to &quot;Who can open it&quot;">​</a></h2><ul><li><strong>Admin is a role on the account</strong> (<code>member</code> or <code>admin</code>), not a scope anyone can ask for (<a href="./adr/0020-every-credential-resolves-to-one-caller">ADR 0020</a>).</li><li><strong>Only the website&#39;s sign-in reaches it.</strong> An admin route answers 401 to an anonymous caller and 403 to anyone who is not an admin signed in through the website: a member, an admin on the phone app, a personal access token or a third-party app.</li><li><strong>One admin for now.</strong> There are no finer rights.</li></ul><h2 id="making-the-first-admin" tabindex="-1">Making the first admin <a class="header-anchor" href="#making-the-first-admin" aria-label="Permalink to &quot;Making the first admin&quot;">​</a></h2><p>No endpoint makes an admin. Set <code>ADMIN_EMAIL</code> in the <code>production</code> environment (<a href="./releasing#deploy-the-server">Releasing</a>) and deploy: when the server starts, the confirmed account with that address becomes an admin. An address with no confirmed account does nothing, so signing up first with someone else&#39;s address cannot take the role. The promotion is written to the audit log.</p><h2 id="the-audit-log" tabindex="-1">The audit log <a class="header-anchor" href="#the-audit-log" aria-label="Permalink to &quot;The audit log&quot;">​</a></h2><p>An admin action is an <code>AdminAction</code> event (who, what, the target), sent through http4k&#39;s <code>Events</code> like any other event. One sink stores it in the <code>admin_audit</code> table (who is empty when the server itself did it, as at start-up; rows stay when the admin&#39;s own account is deleted), and another prints it to the server log, which the log shipping picks up. <code>GET /api/v1/admin/audit</code> returns the last 100 rows, and the first screen of the admin shows them. Each admin feature emits an <code>AdminAction</code> for its writes; tests check it with <code>RecordingEvents</code>.</p><p>Sensitive values are values4k types that print masked: <code>EmailAddress</code> prints as <code>a***@example.com</code>, so an address that reaches a log or an event by accident stays hidden, and the real one is read with <code>.value</code> only where it is needed. An event never carries a password or an unmasked address.</p><h2 id="what-comes-next" tabindex="-1">What comes next <a class="header-anchor" href="#what-comes-next" aria-label="Permalink to &quot;What comes next&quot;">​</a></h2><p>Accounts (<a href="https://github.com/tkint/coach-poulpy/issues/336" target="_blank" rel="noreferrer">#336</a>), the mail from-address (<a href="https://github.com/tkint/coach-poulpy/issues/339" target="_blank" rel="noreferrer">#339</a>), the status view (<a href="https://github.com/tkint/coach-poulpy/issues/340" target="_blank" rel="noreferrer">#340</a>), and the catalog (<a href="https://github.com/tkint/coach-poulpy/issues/337" target="_blank" rel="noreferrer">#337</a>, <a href="https://github.com/tkint/coach-poulpy/issues/338" target="_blank" rel="noreferrer">#338</a>).</p>',11)])])}const u=a(r,[["render",i]]);export{p as __pageData,u as default};
